CREATE TABLE categories (id TEXT PRIMARY KEY, label TEXT NOT NULL, title TEXT NOT NULL, intro TEXT NOT NULL DEFAULT '', footnote TEXT NOT NULL DEFAULT '', position INTEGER NOT NULL);
CREATE TABLE drinks (id TEXT PRIMARY KEY, name TEXT NOT NULL CHECK(length(name) BETWEEN 1 AND 120), details TEXT NOT NULL DEFAULT '', category TEXT NOT NULL REFERENCES categories(id), available INTEGER NOT NULL DEFAULT 1 CHECK(available IN (0,1)), position INTEGER NOT NULL, version INTEGER NOT NULL DEFAULT 1, edited_by TEXT, edited_at INTEGER);
CREATE INDEX drinks_public ON drinks(available,position);

